  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-01-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "一月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-02-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "二月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-03-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "三月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-04-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "四月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-05-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "五月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-06-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "六月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-07-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "七月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-08-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "八月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-09-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "九月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-10-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "十月"; --ios-month-original-size: 0px; }
  .nuo-cal-month:has(.nuo-cal-cell[data-date*="-11-"][data-date$="-15"] .nuo-cal-day) { --ios-month-label: "十一月"; --ios-month-original-size: 0px; }
