/* =================================== */
/* 语音气泡 */
/* =================================== */
:root{
  --voice-bubble-width:80px;
  --voice-fake-time:"13\"";
  --voice-icon-size:19px;
  --voice-text-size:12px;
  --voice-me-icon-x:5px;
  --voice-me-icon-y:0px;
  --voice-me-text-x:6px;
  --voice-me-text-y:0px;
  --voice-them-icon-x:-4px;
  --voice-them-icon-y:0px;
  --voice-them-text-x:-8px;
  --voice-them-text-y:0px;
  --voice-dl-offset:-35px;
}
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg){
  background:transparent!important;
  box-shadow:none!important;
  border:none!important;
  padding:0!important;
}
.bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has(.voice-msg)::before{display:none!important;}
.voice-msg{
  display:flex!important;
  flex-direction:column!important;
  width:fit-content!important;
  max-width:100%!important;
  min-width:0!important;
  padding:0!important;
  margin:0!important;
  position:relative!important;
  overflow:visible!important;
}
.voice-msg-me{align-items:flex-end!important;}
.voice-msg-them{align-items:flex-start!important;}
.voice-controls-row{
  width:var(--voice-bubble-width)!important;
  height:36px!important;
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  display:flex!important;
  align-items:center!important;
  padding:0!important;
  margin:0!important;
}
.voice-msg-me .voice-controls-row{background-color:var(--bubble-me-bg)!important;}
.voice-msg-them .voice-controls-row{background-color:var(--bubble-them-bg)!important;}
.voice-msg-me .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-msg-them .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-them-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-waveform,.voice-duration{display:none!important;}
.voice-play-btn{
  width:100%!important;
  height:100%!important;
  display:flex!important;
  align-items:center!important;
  background:transparent!important;
  border:none!important;
  padding:0 12px!important;
  box-sizing:border-box!important;
  position:relative!important;
}
.voice-msg-me .voice-play-btn{justify-content:flex-end!important;}
.voice-msg-them .voice-play-btn{justify-content:flex-start!important;}
.voice-msg-me .voice-play-btn::before{
  content:var(--voice-fake-time);
  font-size:var(--voice-text-size)!important;
  color:var(--bubble-me-color)!important;
  margin-right:6px!important;
  transform:translate(var(--voice-me-text-x),var(--voice-me-text-y))!important;
}
.voice-msg-me .voice-play-btn::after{
  content:"";
  display:block;
  width:var(--voice-icon-size)!important;
  height:var(--voice-icon-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/623bc1a2-ed39-4ad7-bb3e-6470eb61ad60.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-me-icon-x),var(--voice-me-icon-y))!important;
}
.voice-msg-them .voice-play-btn::before{
  content:"";
  display:block;
  width:var(--voice-icon-size)!important;
  height:var(--voice-icon-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/623bc1a2-ed39-4ad7-bb3e-6470eb61ad60.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-them-icon-x),var(--voice-them-icon-y)) scaleX(-1)!important;
}
.voice-msg-them .voice-play-btn::after{
  content:var(--voice-fake-time);
  font-size:var(--voice-text-size)!important;
  color:var(--bubble-them-color)!important;
  margin-left:6px!important;
  transform:translate(var(--voice-them-text-x),var(--voice-them-text-y))!important;
}
@media (prefers-color-scheme: dark) {
  body .voice-msg-them .voice-play-btn::before{
    filter:invert(1) opacity(var(--dark-icon-opacity,.8))!important;
  }
}
.voice-play-btn svg{
  display:block!important;
  position:absolute!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  width:30px!important;
  height:100%!important;
  opacity:0!important;
  z-index:10!important;
}
.voice-msg-me .voice-play-btn svg{right:0!important;left:auto!important;}
.voice-msg-them .voice-play-btn svg{left:0!important;right:auto!important;}
.voice-download-btn{
  display:flex!important;
  opacity:0!important;
  position:absolute!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  width:30px!important;
  height:30px!important;
  z-index:5!important;
}
.voice-msg-me .voice-download-btn{left:var(--voice-dl-offset)!important;}
.voice-msg-them .voice-download-btn{right:var(--voice-dl-offset)!important;}
.voice-transcription-toggle{
  display:block!important;
  position:absolute!important;
  top:0!important;
  left:0!important;
  width:100%!important;
  height:40px!important;
  opacity:0!important;
  z-index:5!important;
  margin:0!important;
  padding:0!important;
}
.voice-transcription{
  display:block!important;
  position:relative!important;
  top:auto!important;
  left:auto!important;
  right:auto!important;
  margin-top:-2px!important;
  width:fit-content!important;
  max-width:72vw!important;
  background:#FFFFFF!important;
  border-radius:5px!important;
  padding:9px 11px!important;
  color:#000000!important;
  font-size: 15px !important;
  line-height:1.2!important;
  white-space:pre-wrap!important;
  word-wrap:break-word!important;
  word-break:break-all!important;
  box-shadow: none !important;
  z-index:20!important;
  animation:none!important;
}
@media (prefers-color-scheme: dark) {
  body .voice-transcription{
    background:#2C2C2C!important;
    color:#FFFFFF!important;
    border:1px solid none !important;
  }
}
.voice-controls-row .voice-retry-btn,
.voice-controls-row .voice-error-btn,
.voice-controls-row button:not(.voice-play-btn):not(.voice-download-btn){
  display:none!important;
  opacity:0!important;
  pointer-events:none!important;
}

