}
:root {
  --redpacket-opened-icon-size: 50px;
  --redpacket-opened-icon-top: 15px;
  --redpacket-opened-icon-left: 8px;
  --redpacket-opened-text-x: 0px;
  --redpacket-opened-text-y: -18px;
}
.msg-redpacket-card.msg-transfer-success .msg-redpacket-emoji::before {
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/8e1469a7-4edf-421b-85d8-70eedf36dfb5.png') !important;
  width: var(--redpacket-opened-icon-size) !important;
  height: var(--redpacket-opened-icon-size) !important;
  top: var(--redpacket-opened-icon-top) !important;
  left: var(--redpacket-opened-icon-left) !important;
}
.msg-redpacket-card .msg-transfer-amount-section {
  display: none !important;
}

.msg-me .msg-redpacket-card.msg-transfer-success .msg-transfer-content::after,
.bubble-me-custom .msg-redpacket-card.msg-transfer-success .msg-transfer-content::after {
  content: "恭喜发财，大吉大利\A已领取" !important;
  white-space: pre-wrap !important;
