.msg-them .msg-redpacket-card.msg-transfer-success .msg-transfer-content::after,
.bubble-them-custom .msg-redpacket-card.msg-transfer-success .msg-transfer-content::after {
  content: "恭喜发财，大吉大利\A已领取" !important;
  white-space: pre-wrap !important;
  line-height: 1.5 !important;
  transform: translate(var(--redpacket-opened-text-x), var(--redpacket-opened-text-y)) !important;
}

/* =========================================================
   聊天记录卡片气泡 
   ========================================================= */
.msg-history-card {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    padding: 10 !important; 
}

.msg-history-card, 
.msg-history-card * {
    color: var(--bubble-them-color) !important;
    -webkit-text-fill-color: var(--bubble-them-color) !important;
}

.bubble-me-custom:has(.msg-history-card),
.bubble-them-custom:has(.msg-history-card) {
    background-color: var(--bubble-them-bg) !important;
}

.bubble-me-custom:has(.msg-history-card)::before {
    background-color: var(--bubble-them-bg) !important;
}

.msg-history-card * {
    border-top: none !important;
    border-bottom: none !important;
}
.msg-history-card hr {
    display: none !important;
}

.msg-history-card > div:last-child {

    font-size: 0 !important;
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;

    display: block !important;
    min-height: 16px !important;
    padding: 0 !important;
    margin-top: 6px !important;
    position: relative !important;
}

.msg-history-card > div:last-child * {
    display: none !important;
}

.msg-history-card > div:last-child::before {
    content: "聊天记录" !important;
    display: block !important;
    font-size: 11px !important;

    color: var(--bubble-them-color) !important;
    -webkit-text-fill-color: var(--bubble-them-color) !important;

    opacity: 0.5 !important;
    position: absolute !important;
    left: 0 !important;
    top: 0 !important;
    z-index: 5 !important;
}

.msg-history-card > div:not(:first-child):not(:last-child),
.msg-history-card > div:not(:first-child):not(:last-child) * {

    color: var(--bubble-them-color) !important;
    -webkit-text-fill-color: var(--bubble-them-color) !important;

    opacity: 0.7 !important;
}
.msg-history-card > div:first-child::after {
    content: "的聊天记录" !important;

    font-size: inherit !important;
    font-weight: inherit !important;
    color: inherit !important;
    -webkit-text-fill-color: inherit !important;
}
/* 旁白完全复刻时间戳样式 */
:root {
  --narration-bg: var(--sys-msg-bg);
  --narration-color: var(--sys-msg-color);
  --narration-radius: var(--sys-msg-radius);
  --narration-padding: var(--sys-msg-padding);
  --narration-size: var(--sys-msg-font-size);
  --narration-backdrop: var(--sys-msg-backdrop);
  --narration-border: none;
  --narration-shadow: none;
  --narration-style: normal; 
}
/* 系统消息（撤回等）完全复刻时间戳样式 */
:root {
  --system-msg-bg: var(--sys-msg-bg);
  --system-msg-color: var(--sys-msg-color);
  --system-msg-radius: var(--sys-msg-radius);
  --system-msg-padding: var(--sys-msg-padding);
  --system-msg-size: var(--sys-msg-font-size);
  --system-msg-border: none;
  --system-msg-shadow: none;
}
/* 🍓文字图 by小芋 */
:root {
    --msg-sim-border: 1px solid rgba(213, 213, 213, 0.03);
    --msg-sim-shadow: 0 0 3px rgba(0, 0, 0, 0.03), 
inset 0px 0px 1px 1px rgba(255,255,255,0.07);
    --msg-sim-img1: url("https://nos.netease.com/vcloud-statistic/nrtc/17a0c452-41e8-4b3c-9cba-7558ad826f01.jpg");
    --msg-sim-img2: url("https://nos.netease.com/vcloud-statistic/nrtc/288a9ff8-4cf7-4bcb-925a-d74fd0a62271.png");
    --msg-sim-img3: url("https://nos.netease.com/vcloud-statistic/nrtc/2cc3c987-827d-460e-b77c-a968ab2f523e.png");
}
/* 文字图 */
.msg-sim-card * {
    display: none !important;
}
.msg-sim-card {
    position: relative !important;
    overflow: visible !important;
    width: 160px !important;
    height: 210px !important;background-origin: border-box !important;
    background-clip: border-box !important;
    background-image: var(--msg-sim-img1) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border-radius: 10px !important;
    border: var(--msg-sim-border) !important;
    box-shadow: var(--msg-sim-shadow) !important;
    margin-right: 26px !important;
}
.msg-sim-card::before {
    background-image: var(--msg-sim-img2) !important;
    transform: translateX(20px) rotate(2.5deg) scale(0.9) !important;
    z-index: -1 !important;
}
.msg-sim-card::after {
    background-image: var(--msg-sim-img3) !important;
    transform: translateX(37px) rotate(4.5deg) scale(0.8) !important;
    z-index: -2 !important;
}
.msg-sim-card::before,
.msg-sim-card::after {
    content: "" !important;
    position: absolute !important;
    inset: -0.5px  !important;
    width: 100% !important;
    height: 100% !important;
    border-radius: 10px !important;
    border: var(--msg-sim-border) !important;
    box-shadow: var(--msg-sim-shadow) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    pointer-events: none !important;
}
.msg-system {
  margin: 12px auto !important;
  width: fit-content !important;
}
/* 专门去除位置卡片的气泡小角 */
:is(.bubble-me-custom, .bubble-them-custom):has(.msg-loc-card)::before,
:is(.bubble-me-custom, .bubble-them-custom):has(.msg-loc-card)::after {
  display: none !important;
  content: none !important;
}
