/* ==========================================
   PART 2: 全局排版、隐藏与滚动条消灭
   ========================================== */
:root {
    --forum-page-bg: var(--tw-bg); --forum-post-bg: var(--tw-bg); --forum-chrome-bg: var(--tw-bg); --forum-chrome-nav-bg: var(--tw-bg); --forum-tabs-bg: var(--tw-bg); --forum-board-card-bg: var(--tw-bg); --forum-board-hero-bg: var(--tw-bg); --forum-profile-bg: var(--tw-bg); --forum-profile-header-bg: var(--tw-bg); --forum-profile-stats-bg: var(--tw-bg); --forum-message-item-bg: var(--tw-bg); --forum-comment-input-bar-bg: var(--tw-bg);
    --forum-text: var(--tw-text); --forum-chrome-title-color: var(--tw-text); --forum-chrome-icon-color: var(--tw-text); --forum-comment-input-color: var(--tw-text);
    --forum-text-muted: var(--tw-muted);
    --forum-divider: var(--tw-border); --forum-chrome-nav-border: 1px solid var(--tw-border); --forum-tabs-border: 1px solid var(--tw-border); --forum-comment-input-bar-border: 1px solid var(--tw-border); --forum-board-card-border: 1px solid var(--tw-border);
    --forum-comment-input-bg: var(--tw-input); --forum-board-icon-bg: var(--tw-icon-bg);
    --forum-accent: #1d9bf0; --forum-post-radius: 0px; --forum-post-border: none; --forum-post-shadow: none; --forum-comment-input-radius: 9999px; --forum-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

    --forum-scrollbar-width: 0px; --forum-scrollbar-thumb-bg: transparent; --forum-scrollbar-track-bg: transparent;
}
.nuo-forum-root ::-webkit-scrollbar, .nuo-forum-root *::-webkit-scrollbar { width: 0px !important; height: 0px !important; display: none !important; background: transparent !important; }

.nuo-forum-root .nuo-forum-feed > div:not(:has(.nuo-forum-post)):not(:has(.feed-tab)):not(:has(input)):not([class*="search"]):not(:has(.nuo-forum-tabs)):not(.nuo-forum-tabs),
.nuo-forum-root [class*="tag"], .nuo-forum-root [class*="badge"], .nuo-forum-root [class*="level"] { display: none !important; }
.nuo-forum-root .nuo-forum-chrome-header { z-index: 9999 !important; position: relative !important; }
.nuo-forum-root .nuo-forum-chrome-header, .nuo-forum-root .nuo-forum-chrome-title, .nuo-forum-root .nuo-forum-chrome-header * { color: var(--tw-text) !important; fill: var(--tw-text) !important; stroke: var(--tw-text) !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-post-detail-view *, .nuo-forum-root .nuo-forum-comment-content, .nuo-forum-root .nuo-forum-comment-author, .nuo-forum-root .nuo-forum-comments-header { color: var(--tw-text) !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-me *, .nuo-forum-root .nuo-forum-profile *, .nuo-forum-root .nuo-forum-messages-list *, .nuo-forum-root [class*="message"] *, .nuo-forum-root .nuo-forum-board-hero * { color: var(--tw-text) !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-boards-list * { color: var(--tw-text) !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-board-card svg, .nuo-forum-root .nuo-forum-board-card [class*="stat"], .nuo-forum-root .nuo-forum-board-card [class*="meta"], .nuo-forum-root .nuo-forum-boards-list [class*="desc"], .nuo-forum-root .nuo-forum-message-preview, .nuo-forum-root .nuo-forum-board-desc, .nuo-forum-root .nuo-forum-board-hero [class*="desc"] { color: var(--tw-muted) !important; fill: var(--tw-muted) !important; }
.nuo-forum-root .nuo-forum-comments, .nuo-forum-root .nuo-forum-comment { background-color: var(--tw-bg) !important; }
.nuo-forum-root .nuo-forum-boards-list, .nuo-forum-root .nuo-forum-board-detail, .nuo-forum-root .nuo-forum-messages-list, .nuo-forum-root .nuo-forum-profile, .nuo-forum-root .nuo-forum-me, .nuo-forum-root [class*="message"], .nuo-forum-root [class*="chat"] { background-color: var(--tw-bg) !important; background: var(--tw-bg) !important; }
.nuo-forum-root [class*="chat"][class*="bar"], .nuo-forum-root [class*="message"][class*="bar"], .nuo-forum-root [class*="footer"] { background-color: var(--tw-bg) !important; border-top: 1px solid var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-boards-list > div:first-child, .nuo-forum-root [class*="search"] { background-color: var(--tw-bg) !important; }
.nuo-forum-root .nuo-forum-me div, .nuo-forum-root .nuo-forum-profile div, .nuo-forum-root .nuo-forum-board-card { background-color: var(--tw-bg) !important; border-color: var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-chrome-nav { background-color: var(--tw-bg) !important; background-image: none !important; border-top: 1px solid var(--tw-border) !important; }

/* ==========================================
   PART 3: 全局输入框与评论区重组
   ========================================== */
.nuo-forum-root [class*="chat"] input, .nuo-forum-root [class*="chat"] textarea, .nuo-forum-root [class*="message"] input, .nuo-forum-root [class*="message"] textarea, .nuo-forum-root .nuo-forum-boards-list input, .nuo-forum-root [class*="search"] input { background-color: var(--tw-input) !important; color: var(--tw-text) !important; border: none !important; border-radius: 9999px !important; padding-left: 16px !important; padding-right: 16px !important; }
.nuo-forum-root .nuo-forum-comment-input::-webkit-input-placeholder, .nuo-forum-root .nuo-forum-comment-input::placeholder { color: transparent !important; }
.nuo-forum-root .nuo-forum-comment-input:placeholder-shown { background-image: var(--tw-reply-placeholder) !important; background-repeat: no-repeat !important; background-position: 12px center !important; }
.nuo-forum-root .nuo-forum-comments { padding-left: 0 !important; padding-right: 0 !important; }
.nuo-forum-root .nuo-forum-comments-header { padding-left: 16px !important; padding-right: 16px !important; border-bottom: 1px solid var(--tw-border) !important; }
.nuo-forum-root .nuo-forum-comment { margin: 0 !important; border-radius: 0 !important; padding: 12px 16px !important; border-bottom: 1px solid var(--tw-border) !important; }

/* ==========================================
   PART 4: 帖子紧凑排版与推特数据栏
   ========================================== */
.nuo-forum-root [class*="avatar"], .nuo-forum-root [class*="avatar"] img { width: 40px !important; height: 40px !important; border-radius: 50% !important; overflow: hidden !important; object-fit: cover !important; flex-shrink: 0 !important; }
.nuo-forum-root .nuo-forum-board-card [class*="avatar"], .nuo-forum-root .nuo-forum-board-card [class*="avatar"] img, .nuo-forum-root .nuo-forum-board-hero [class*="avatar"], .nuo-forum-root .nuo-forum-board-hero [class*="avatar"] img { width: 20px !important; height: 20px !important; }
.nuo-forum-root .nuo-forum-post { position: relative !important; display: block !important; padding: 12px 16px 34px 68px !important; margin: 0 !important; border-radius: 0 !important; border-bottom: 1px solid var(--tw-border) !important; background-color: var(--tw-bg) !important; color: var(--tw-text) !important; }
.nuo-forum-root .nuo-forum-post:active, .nuo-forum-root .nuo-forum-post:hover { background-color: var(--tw-hover) !important; }
.nuo-forum-root .nuo-forum-post-author-name { position: absolute !important; top: 12px !important; left: 68px !important; font-size: 15px !important; font-weight: 700 !important; line-height: 1.2 !important; white-space: nowrap !important; overflow: visible !important; opacity: 1 !important; color: var(--tw-text) !important; }
.nuo-forum-root .nuo-forum-post-author-name span { font-weight: 400 !important; margin-left: 4px !important; color: var(--tw-muted) !important; }
.nuo-forum-root .nuo-forum-post-time { position: absolute !important; top: 12px !important; right: 16px !important; font-size: 14px !important; line-height: 1.2 !important; color: var(--tw-muted) !important; }
.nuo-forum-root .nuo-forum-post-title, .nuo-forum-root .nuo-forum-post-title *, .nuo-forum-root .nuo-forum-post-excerpt, .nuo-forum-root .nuo-forum-post-excerpt * { margin-top: 18px !important; margin-bottom: 0 !important; font-size: 15px !important; font-weight: 400 !important; line-height: 1.4 !important; display: block !important; color: var(--tw-text) !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-post [class*="avatar"] { position: absolute !important; top: 12px !important; left: 16px !important; margin: 0 !important; z-index: 2 !important; }
.nuo-forum-root .nuo-forum-post:not(:has([class*="avatar"]))::before, .nuo-forum-root .nuo-forum-comment:not(:has([class*="avatar"]))::before { content: ''; position: absolute !important; top: 12px !important; left: 16px !important; width: 40px !important; height: 40px !important; border-radius: 50% !important; overflow: hidden !important; background-image: var(--tw-anon-avatar) !important; background-size: cover !important; z-index: 1 !important; }
.nuo-forum-root [class*="avatar"]:not(:has(img)):not([style*="background"]) { background-image: var(--tw-anon-avatar) !important; background-size: cover !important; color: transparent !important; }
.nuo-forum-root .nuo-forum-post { background-image: var(--tw-data-a) !important; background-position: 68px calc(100% - 8px) !important; background-size: 290px 20px !important; background-repeat: no-repeat !important; }
.nuo-forum-root .nuo-forum-post:nth-of-type(even) { background-image: var(--tw-data-b) !important; }
.nuo-forum-root .nuo-forum-post-media, .nuo-forum-root .nuo-forum-post-media * { color: #1a1a1a !important; text-shadow: 0 0 4px rgba(255, 255, 255, 0.9) !important; opacity: 1 !important; }

/* ==========================================
   PART 5: 隐形映射分享键
   ========================================== */
.nuo-forum-root .nuo-forum-post-metrics, .nuo-forum-root .nuo-forum-post-stats, .nuo-forum-root .nuo-forum-post-actions { display: block !important; position: absolute !important; bottom: 0 !important; left: 0 !important; width: 100% !important; height: 34px !important; opacity: 0 !important; z-index: 10 !important; pointer-events: none !important; }
.nuo-forum-root .nuo-forum-post-metrics > *, .nuo-forum-root .nuo-forum-post-stats > *, .nuo-forum-root .nuo-forum-post-actions > * { display: none !important; }
.nuo-forum-root .nuo-forum-post-actions > *:last-child, .nuo-forum-root .nuo-forum-post-metrics > *:last-child, .nuo-forum-root .nuo-forum-post [class*="share"] { display: block !important; position: absolute !important; bottom: 0 !important; left: 320px !important; width: 50px !important; height: 34px !important; pointer-events: auto !important; cursor: pointer !important; }

/* ==========================================
   PART 6: 首页推特顶栏重构 (按字数完美补偿平分版)
   ========================================== */
body .nuo-forum-root .nuo-forum-feed > div:has(.feed-tab) { 
    display: flex !important; position: relative !important; background-color: var(--tw-bg) !important; 
    border-bottom: 1px solid var(--tw-border) !important; height: 50px !important; width: 100% !important;
    padding: 0 50px 0 16px !important; margin: 0 !important; z-index: 20 !important; box-sizing: border-box !important;
}
body .nuo-forum-root .nuo-forum-feed *:has(> .feed-tab) { display: flex !important; width: 100% !important; height: 100% !important; padding: 0 !important; margin: 0 !important; transform: none !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab { position: relative !important; height: 50px !important; display: flex !important; align-items: center !important; justify-content: center !important; background: transparent !important; border: none !important; box-shadow: none !important; margin: 0 !important; padding: 0 !important; color: transparent !important; -webkit-tap-highlight-color: transparent !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab * { display: none !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(1) { order: 1 !important; flex: 3.5 !important; } 
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(3) { order: 2 !important; flex: 4 !important; } 
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(2) { order: 3 !important; flex: 2.5 !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab::before { display: block !important; position: absolute !important; top: 50% !important; left: 50% !important; transform: translate(-50%, -50%) !important; font-size: 15px !important; font-weight: 700 !important; color: var(--tw-muted) !important; z-index: 2 !important; pointer-events: none !important; white-space: nowrap !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab.active::before { color: var(--tw-text) !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(1)::before { content: "为你推荐" !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(3)::before { content: "正在关注" !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(2)::before { content: "最新" !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab.active::after { content: '' !important; position: absolute !important; bottom: 0 !important; left: 50% !important; transform: translateX(-50%) !important; height: 3px !important; background-color: var(--forum-accent, #1d9bf0) !important; border-radius: 1px !important; z-index: 3 !important; pointer-events: none !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(1).active::after { width: 76px !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(3).active::after { width: 76px !important; }
body .nuo-forum-root .nuo-forum-feed .feed-tab:nth-child(2).active::after { width: 38px !important; }
body .nuo-forum-root .nuo-forum-feed > div:has(.feed-tab)::after { content: '+' !important; position: absolute !important; top: 0 !important; right: 0 !important; width: 50px !important; height: 50px !important; display: flex !important; align-items: center !important; justify-content: center !important; font-size: 28px !important; font-weight: 400 !important; color: var(--tw-muted) !important; pointer-events: none !important; z-index: 10 !important; transform: translateY(-2.5px) !important; }

/* ==========================================
   PART 7: 用户专供安全弹窗补丁 (分享卡片)
   ========================================== */
.nuo-forum-root .fanfic-modal-overlay { background: rgba(0, 0, 0, 0.6) !important; }
.nuo-forum-root .fanfic-custom-panel, .nuo-forum-root .fanfic-ask-dialog { background: var(--tw-bg, #fff) !important; color: var(--tw-text, inherit) !important; border: 1px solid var(--tw-border, transparent) !important; border-radius: 16px !important; box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25) !important; }
.nuo-forum-root .fanfic-custom-header, .nuo-forum-root .fanfic-custom-body, .nuo-forum-root .fanfic-custom-footer { background: transparent !important; color: var(--tw-text, inherit) !important; }
