data.css:
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 100%; height: 100%; overflow: hidden; }
body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif; }

.widget {
  position: relative;
  width: 100%; height: 100%;
  border-radius: 24px;
  overflow: hidden;
  display: flex; flex-direction: column; justify-content: space-between;
  padding: 12px 14px;
}

.bg-layer {
  position: absolute; inset: 0;
  background-image: url({{bgImage}});
  background-size: cover;
  background-position: center;
  z-index: 0;
}
.bg-tint {
  position: absolute; inset: 0;
  z-index: 1;
  transition: background .3s ease;
}

.top-row { position: relative; z-index: 2; display: flex; align-items: center; gap: 8px; }
.avatar { border-radius: 50%; object-fit: cover; background: #ddd; }
.avatar-left { width: 34px; height: 34px; box-shadow: 0 2px 6px rgba(0,0,0,0.15); }
.label-left { font-size: 13px; font-weight: 600; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.center-col { position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; gap: 3px; }
.time { font-size: 28px; font-weight: 800; color: #fff; letter-spacing: 1px; line-height: 1; }
.quote { font-size: 11px; color: rgba(255,255,255,0.85); }

.bottom-row {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}
.pill {
  background: rgba(255,255,255,0.85);
  border-radius: 999px;
  padding: 6px 14px;
  margin-right: 8px;
  overflow: hidden;
}
.label-pill { font-size: 11px; font-weight: 600; color: #333; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.avatar-right {
  width: 34px; height: 34px;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}

.mz-cat-clock, .mz-cat-clock * {
  -webkit-tap-highlight-color: transparent !important;
  -webkit-user-select: none !important;
  user-select: none !important;
  outline: none !important;
}

.mz-cat-clock {
  container-type: inline-size;
  width: 100%; height: 100%; position: relative;
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: clamp(16px, 6cqw, 24px);
  background: var(--bg-clock); 
  display: flex; align-items: center; justify-content: center;
}

.clock-container {
  position: relative; 
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
}

.cat-face {
  position: relative;
  display: flex; align-items: center; justify-content: center;
  padding: clamp(10px, 3cqw, 20px) clamp(30px, 8cqw, 60px); 
}

.time-text {
  margin-top: clamp(15px, 5cqw, 30px);
  font-size: var(--s-time);
  /* 直接锁定最标准的粗体，告别多层阴影带来的重影问题 */
  font-weight: 700;
  color: var(--c-time);
  letter-spacing: clamp(1px, 0.5cqw, 4px);
  line-height: 1;
  position: relative;
  z-index: 5;
  display: flex; align-items: center;
}

.colon {
  margin: 0 clamp(4px, 1cqw, 8px);
  opacity: 1; 
  padding-bottom: clamp(6px, 1.5cqw, 10px); 
}

/* =========================================
   🐾 SVG 定位 
========================================= */
.svg-icon { position: absolute; z-index: 10; }
.svg-icon svg { overflow: visible !important; }

.ear-outline { stroke: var(--c-ear); }
.ear-inner { fill: var(--c-ear); stroke: var(--c-ear); }
.whisker-left svg, .whisker-right svg { stroke: var(--c-whisker); }

.ear-left {
  width: clamp(55px, 16cqw, 90px); height: clamp(55px, 16cqw, 90px);
  top: clamp(-30px, -8cqw, -55px);
  left: clamp(-5px, -1cqw, -15px);
  transform: rotate(-10deg);
}
.ear-right {
  width: clamp(55px, 16cqw, 90px); height: clamp(55px, 16cqw, 90px);
  top: clamp(-30px, -8cqw, -55px);
  right: clamp(-5px, -1cqw, -15px);
  transform: rotate(10deg);
}

.whisker-left {
  width: clamp(30px, 9cqw, 55px); height: clamp(60px, 18cqw, 100px);
  top: 72%; transform: translateY(-50%);
  left: clamp(-30px, -7cqw, -45px); 
}
.whisker-right {
  width: clamp(30px, 9cqw, 55px); height: clamp(60px, 18cqw, 100px);
  top: 72%; transform: translateY(-50%);
  right: clamp(-30px, -7cqw, -45px);
}

body { margin: 0; padding: 0 0px; box-sizing: border-box; font-family: -apple-system, sans-serif; background: transparent; height: 100%; display: flex; align-items: center; }
.widget { width: 100%; background: #fff; border-radius: 24px; padding: 23px; display: flex; flex-direction: column; gap: 24px; box-sizing: border-box; }
.search-box { background: #f5f5f5; border-radius: 20px; padding: 9px 16px; display: flex; justify-content: space-between; align-items: center; }
.search-text { color: #999; font-size: 15px; flex: 1; outline: none; }
.nav { display: flex; justify-content: space-between; align-items: center; margin: 0 -15px}
.nav-item { display: flex; flex-direction: column; align-items: center; gap: 4px; cursor: pointer; flex: 1; }
.nav-item span { font-size: 11px; color: #333; font-weight: 500; }

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

value.css:
/* 微信_切换日夜间7by池谕 — nuojiji messaging app theme */

/* ==========================================
   糯叽机 · 微信高仿主题终整理版
========================================== */

/* ========== 1. 全局变量与基础底色 ========== */
#messaging-chat-tab,
#messaging-moments-tab,
#messaging-profile-tab,
#messaging-favorites-tab,
.nj-tab-bottom-bar {
    --nj-msg-bg: #ededed;
    --nj-msg-chat-bg: #ffffff;
    --nj-msg-card-bg: #ffffff;
    --nj-msg-card-bg-pinned: #efefef;
    --nj-msg-card-radius: 0px;
    --nj-msg-card-border: none;
    --nj-msg-card-gap: 0px;
    --nj-msg-text: #191919;
    --nj-msg-text-muted: #b2b2b2;
    --nj-msg-text-time: #b2b2b2;
    --nj-msg-avatar-radius: 5px;
    --nj-msg-avatar-shadow: none;
    --nj-msg-tabbar-active: #07c160;
    --nj-msg-tabbar-bg: #f7f7f7;
    --nj-msg-card-active-transform: none;
    --nj-msg-card-hover-transform: none;
    --nj-msg-card-transition: background-color 0.1s;
    --nj-msg-moments-cover-height: 350px;
/* 👇 小白设置区：左上角五角星开关 👇 */
/* 填 block 是显示，填 none 是隐藏 */
    --show-top-star: block;
}


/* ========== 2. 聊天列表 (微信首页) ========== */
/* 解决色差：正规撑满大法 */
#messaging-chat-tab {
    display: flex !important;
    flex-direction: column !important;
    --nj-msg-chat-bg: #ededed !important;
}
.nj-chat-tab-list {
    flex-grow: 1 !important;
    background: #ffffff !important;
    padding-bottom: calc(-5px + var(--nuo-safe-bottom)) !important;
}

/* 聊天列表项与间距 */
.nj-chat-item {
    margin: 0 !important;
    padding: 12px 16px !important;
    box-shadow: none !important;
    position: relative !important;
}
.nj-chat-item:active {
    background-color: #d9d9d9 !important;
}
.nj-chat-item-name {
    margin-bottom: 0px !important; 
    line-height: 1.2 !important;
}
.nj-chat-item-preview {
    margin-top: 4.5px !important;
    line-height: 1.2 !important;
    margin-right: 3px !important;
    text-overflow: ellipsis !important;
    display: block !important;
}
.nj-chat-item-time {
    font-size: 11px !important; 
    font-weight: 420 !important;
    color: #999999 !important;
    opacity: 0.5 !important; 
    transform: translateY(-2px) !important; 
}
/* 去大头钉 */
.nj-chat-item-pin-mark { display: none !important; }
/* 微信原味短分割线（避开头像） */
.nj-chat-item::after {
content: '' !important;
position: absolute !important;
bottom: 0 !important;
left: 74px !important;
right: 0 !important;
height: 0.2px !important;
background-color: #d6d6d6 !important;
z-index: 1 !important;
}
/* 夜间模式短线 */
[data-color-scheme="dark"] .nj-chat-item::after {
background-color: #383838 !important;
}

